import csv

def load(p):
    with open(p) as f:
        rd = csv.DictReader(f)
        return list(rd), rd.fieldnames

rows, fn = load("ae_ci_age_gender.csv")
print("cols:", fn, "n:", len(rows))
print("sample:", rows[0])

def num(x):
    try:
        return float(str(x).replace(",", "").strip())
    except Exception:
        return 0.0

def find(nm, excl=()):
    for c in fn:
        cl = c.lower()
        if nm in cl and not any(e in cl for e in excl):
            return c
    return None

yl = find("year")
al = find("age")
gl = find("gender") or find("sex")
acl = find("actual")
ecl = find("expected")
print("using:", yl, al, gl, acl, ecl)

ys = sorted({r[yl] for r in rows})
segs = {}
for r in rows:
    k = (r.get(al, "?"), r.get(gl, "?"))
    a, e = segs.get(k, (0.0, 0.0))
    segs[k] = (a + num(r.get(acl)), e + num(r.get(ecl)))

big = sorted([k for k in segs if segs[k][1] >= 100], key=lambda k: -segs[k][1])
print("segments E>=100:", len(big))
print("year  " + "  ".join(ys))
for k in big[:12]:
    cells = []
    for y in ys:
        a = e = 0.0
        for r in rows:
            if r.get(yl) == y and (r.get(al), r.get(gl)) == k:
                a += num(r.get(acl)); e += num(r.get(ecl))
        cells.append(f"{a/e:.3f}" if e > 0 else "   na")
    print(f"{k[0]:>12}/{k[1]:<9} E={segs[k][1]:6.0f}  " + "  ".join(cells))
